  void BuildCity(Transform city,int chapter){var stone=MeshArt.Mat("LobbyCityStone"+chapter,chapter==1?new Color(.17f,.24f,.34f):chapter==2?new Color(.85f,.82f,.69f):new Color(.73f,.52f,.34f));var trim=MeshArt.Mat("LobbyCityTrim"+chapter,chapter==1?new Color(.25f,.56f,.66f):new Color(.91f,.78f,.53f));var roof=MeshArt.Mat("LobbyCityRoof"+chapter,chapter==1?new Color(.11f,.40f,.52f):new Color(.08f,.29f,.30f));var glass=MeshArt.Mat("LobbyCityGlass"+chapter,chapter==1?new Color(.25f,.87f,.96f):new Color(1,.74f,.29f),-1,true);var pink=MeshArt.Mat("LobbyNeonMagenta",new Color(.94f,.23f,.67f),-1,true);
   void Building(string name,float x,float z,float width,float height,float depth,int kind){var root=new GameObject(name).transform;root.SetParent(city,false);root.localPosition=new Vector3(x,0,z);MeshArt.Box(root,"MasonryBlock",new Vector3(0,height/2,0),new Vector3(width,height,depth),stone);MeshArt.Box(root,"Cornice",new Vector3(0,height,0),new Vector3(width+.16f,.15f,depth+.15f),trim);for(int row=0;row<Mathf.FloorToInt(height/.8f);row++)for(int col=0;col<3;col++)MeshArt.Box(root,"WindowRecess",new Vector3((col-1)*width*.28f,.45f+row*.8f,-depth/2-.035f),new Vector3(width*.13f,.32f,.05f),glass);
    if(kind==0){var dome=MeshArt.Lathe(root,"CopperCupola",new[]{0f,.18f,.55f,.90f,1.02f},new[]{width*.42f,width*.42f,width*.34f,width*.15f,0f},20,roof,Vector3.one);dome.transform.localPosition=new Vector3(0,height+.12f,0);}else if(kind==1){var spire=MeshArt.Lathe(root,"ClockSpire",new[]{0f,.6f,1.8f},new[]{width*.42f,width*.34f,0f},8,roof,Vector3.one);spire.transform.localPosition=new Vector3(0,height+.10f,0);}else if(kind==2){MeshArt.Box(root,"TerraceRoof",new Vector3(0,height+.35f,0),new Vector3(width*.72f,.7f,depth*.7f),roof);}else{for(int k=0;k<3;k++)MeshArt.Box(root,"NeonSetback",new Vector3(0,height+.4f+k*.55f,0),new Vector3(width*(.80f-k*.15f),.5f,depth*(.80f-k*.15f)),k==1?pink:roof);for(int k=0;k<3;k++)MeshArt.Box(root,"VerticalLight",new Vector3(-width*.48f+k*width*.48f,height/2,-depth/2-.075f),new Vector3(.045f,height*.85f,.025f),k==1?pink:glass);}}
   if(chapter==0){MeshArt.Box(city,"SunsetCanal",new Vector3(0,-.08f,-1.5f),new Vector3(18,.12f,6.5f),MeshArt.Mat("LobbySunsetWater",new Color(.19f,.48f,.49f)));MeshArt.Box(city,"CanalQuay",new Vector3(0,.02f,2.0f),new Vector3(18,.20f,2.4f),stone);Building("CanalClockTower",-4.9f,2.4f,1.8f,5.4f,2.0f,1);Building("SunsetRotunda",-.8f,3.1f,3.2f,3.1f,2.4f,0);Building("WaterfrontHouse",3.1f,1.7f,2.0f,2.8f,2.2f,2);Building("WaterfrontMansard",5.8f,3.5f,2.2f,4.0f,2.4f,0);Building("DistantBellTower",1.8f,6,1.25f,5.5f,1.4f,1);MeshArt.Box(city,"StoneCanalBridge",new Vector3(-2,.36f,-1.3f),new Vector3(1.7f,.30f,6.4f),trim);for(int side=-1;side<=1;side+=2){MeshArt.Box(city,"BridgeHandrail",new Vector3(-2+side*.75f,.92f,-1.3f),new Vector3(.09f,.12f,6.2f),roof);for(int k=0;k<8;k++)MeshArt.Box(city,"BridgeBaluster",new Vector3(-2+side*.75f,.65f,-4+k*.8f),new Vector3(.055f,.50f,.055f),roof);}MeshArt.Oval(city,"SettingSun",new Vector3(-7,5.8f,7),new Vector3(1.5f,1.5f,.25f),glass,20);
   }else if(chapter==1){MeshArt.Box(city,"NeonRiver",new Vector3(0,-.08f,-1.3f),new Vector3(18,.1f,5),MeshArt.Mat("LobbyNeonWater",new Color(.08f,.21f,.34f)));MeshArt.Box(city,"NightPromenade",new Vector3(0,.02f,1.4f),new Vector3(18,.2f,2.2f),stone);Building("NeonTerracedTower",-4.7f,2,2.2f,5.7f,2.2f,3);Building("NeonLanternTower",-.8f,3.7f,2.6f,6.0f,2.6f,3);Building("NightWaterfront",3.2f,1.9f,2.6f,3.4f,2.4f,2);Building("CyanNeedle",5.6f,4.8f,1.7f,5.6f,1.8f,3);for(int i=0;i<7;i++){float x=-7+i*2.2f;MeshArt.Box(city,"PromenadeLampPost",new Vector3(x,.85f,.10f),new Vector3(.07f,1.7f,.07f),roof);MeshArt.Oval(city,"PromenadeLamp",new Vector3(x,1.7f,.10f),Vector3.one*.26f,i%2==0?glass:pink,8);}for(int i=0;i<8;i++)MeshArt.Box(city,"LightReflection",new Vector3(-6.5f+i*1.9f,-.01f,-1.6f),new Vector3(.15f,.02f,1.4f),i%2==0?glass:pink);
   }else{MeshArt.Box(city,"SkylinePlaza",new Vector3(0,-.1f,1),new Vector3(18,.18f,12),stone);Building("DaylightBellTower",-5.7f,3.5f,1.65f,5.8f,1.8f,1);Building("GalleryPalazzo",4.9f,2.8f,3.5f,3.6f,2.8f,2);var drum=MeshArt.Lathe(city,"GrandDomeDrum",new[]{0f,2.7f,2.85f,3.0f},new[]{2.35f,2.35f,2.55f,2.55f},24,stone,Vector3.one);drum.transform.localPosition=new Vector3(0,0,3.4f);var dome=MeshArt.Lathe(city,"GrandSkylineDome",new[]{0f,.45f,1.1f,1.75f,2.02f},new[]{2.48f,2.40f,1.9f,.85f,.16f},24,roof,Vector3.one);dome.transform.localPosition=new Vector3(0,3.0f,3.4f);for(int i=0;i<9;i++){float a=(i+1)*Mathf.PI/10;MeshArt.Box(city,"RotundaColonnade",new Vector3(Mathf.Cos(a)*2.22f,1.25f,3.4f-Mathf.Sin(a)*2.22f),new Vector3(.17f,2.5f,.17f),trim);}MeshArt.Lathe(city,"PlazaFountain",new[]{0f,.15f,.45f,.50f},new[]{1.05f,1.15f,1.15f,.82f},24,trim,Vector3.one).transform.localPosition=new Vector3(-2,.02f,-1.4f);var leaf=MeshArt.Mat("LobbyPlazaFoliage",new Color(.22f,.43f,.28f));for(int i=0;i<5;i++){float x=-7+i*3.5f;MeshArt.Box(city,"PlazaTreeTrunk",new Vector3(x,.60f,-2.8f),new Vector3(.10f,1.2f,.10f),roof);MeshArt.Oval(city,"PlazaTreeCrown",new Vector3(x,1.55f,-2.8f),new Vector3(.95f,1.45f,.95f),leaf,12);}}
  }
  void BuildCabin(int tower,bool backdrop,int style){LiftArchitecture.Cabin(_scene.transform);LiftArchitecture.Rails(_scene.transform);var cabin=_scene.transform.Find("CopperLiftCabin");float shift=backdrop?-1.4f:0;cabin.localPosition=new Vector3(shift,0,0);foreach(Transform child in _scene.transform)if(child.name=="VerticalLiftRail"||child.name=="CopperRailGuide"||child.name=="RailMount")child.localPosition+=Vector3.right*shift;
   LiftArchitecture.Bay(_scene.transform,0);_scene.transform.Find("ArchitecturalFloorBay").localPosition=new Vector3(backdrop?2.9f:4.0f,0,2.1f);LiftArchitecture.Bay(_scene.transform,0);var bays=_scene.GetComponentsInChildren<Transform>();for(int i=bays.Length-1;i>=0;i--)if(bays[i].name=="ArchitecturalFloorBay"){bays[i].name="LeftAtriumArchitecture";bays[i].localPosition=new Vector3(-4.25f,0,3.4f);break;}
   var stone=MeshArt.Mat("LobbyMarble",new Color(.78f,.76f,.67f));MeshArt.Box(_scene.transform,"LobbyLanding",new Vector3(shift,.35f,0),new Vector3(4.4f,.45f,3.5f),stone);MeshArt.Box(_scene.transform,"AtriumMarbleFloor",new Vector3(0,.10f,2.4f),new Vector3(13,.15f,8),stone);var inlay=MeshArt.Mat("LobbyFloorInlay",new Color(.09f,.29f,.29f));for(int i=0;i<6;i++)MeshArt.Box(_scene.transform,"AtriumFloorInlay",new Vector3(-5+i*2,.19f,2.4f),new Vector3(.035f,.01f,8),inlay);
   var runner=RunnerArt.Build(_scene.transform);runner.transform.localPosition=new Vector3(shift,.66f,-.1f);runner.transform.localRotation=Quaternion.Euler(0,155,0);runner.Style(style>=0?style:tower==1?1:2);_camera.transform.localPosition=new Vector3(7.5f,4.8f,-12);_camera.transform.LookAt(_scene.transform.position+new Vector3(backdrop?.5f:.8f,1.9f,.6f));_camera.backgroundColor=new Color(.89f,.83f,.69f);SetLayer(_scene.transform);}
  void InitializeScene(){_scene=new GameObject("Lobby3DKit");_slot=LeaseSlot();_scene.transform.position=new Vector3(1000+(_slot%8)*SlotSpacing,0,1000+(_slot/8)*SlotSpacing);
   var cameraObject=new GameObject("LobbyPreviewCamera",typeof(Camera));cameraObject.transform.SetParent(_scene.transform,false);_camera=cameraObject.GetComponent<Camera>();_camera.enabled=false;_camera.cullingMask=1<<PreviewLayer;_camera.clearFlags=CameraClearFlags.SolidColor;_camera.backgroundColor=new Color(.89f,.85f,.77f);_camera.orthographic=true;_camera.nearClipPlane=.1f;_camera.farClipPlane=40;_camera.allowHDR=false;cameraObject.transform.localPosition=new Vector3(6.5f,4.6f,-12);cameraObject.transform.LookAt(_scene.transform.position+new Vector3(0,1.7f,.2f));
   var lamp=new GameObject("PreviewSoftbox",typeof(Light));lamp.transform.SetParent(_scene.transform,false);lamp.transform.localPosition=new Vector3(-3,7,-5);lamp.transform.LookAt(_scene.transform.position+Vector3.up);var light=lamp.GetComponent<Light>();light.type=LightType.Spot;light.range=26;light.spotAngle=85;light.intensity=1.8f;light.color=new Color(1,.85f,.66f);light.shadows=LightShadows.None;light.cullingMask=1<<PreviewLayer;
   _target=new RenderTexture(384,384,16,RenderTextureFormat.ARGB32){name="RealLiftLobbyPreview",antiAliasing=2};if(Application.isPlaying)_target.Create();_camera.targetTexture=_target;texture=_target;
  }
  static void SetLayer(Transform root){root.gameObject.layer=PreviewLayer;foreach(Transform child in root)SetLayer(child);}
  void LateUpdate(){if(!Application.isPlaying||_camera==null)return;var size=rectTransform.rect.size;if(size.x<1||size.y<1||(_rendered&&size==_size))return;_size=size;_camera.aspect=size.x/size.y;_camera.orthographicSize=_city?Mathf.Max(5.4f,7.4f/_camera.aspect):Mathf.Max(3.0f,3.7f/_camera.aspect);int pixelsW=Mathf.Clamp(Mathf.CeilToInt(size.x*2),96,768),pixelsH=Mathf.Clamp(Mathf.CeilToInt(size.y*2),96,768);if(_target.width!=pixelsW||_target.height!=pixelsH){_target.Release();_target.width=pixelsW;_target.height=pixelsH;_target.Create();}_camera.Render();_rendered=true;}
  protected override void OnDisable(){base.OnDisable();if(_scene!=null)_scene.SetActive(false);}
  protected override void OnEnable(){base.OnEnable();if(_scene!=null)_scene.SetActive(true);_rendered=false;}
  protected override void OnDestroy(){base.OnDestroy();texture=null;if(_camera!=null)_camera.targetTexture=null;if(_target!=null){_target.Release();Dispose(_target);}if(_scene!=null){_scene.SetActive(false);Dispose(_scene);}if(_slot>=0){Slots[_slot]=false;_slot=-1;}}
  static void Dispose(Object asset){if(Application.isPlaying)Destroy(asset);else DestroyImmediate(asset);}
 }
